import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1786978836000}`),a={name:`reference/environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><p>The complete set. There is no config file and no command-line flag.</p><h2 id="audiobookshelf-url" tabindex="-1"><code>AUDIOBOOKSHELF_URL</code> <a class="header-anchor" href="#audiobookshelf-url" aria-label="Permalink to “AUDIOBOOKSHELF_URL”">​</a></h2><p><strong>Required.</strong> Base URL of the Audiobookshelf instance, e.g. <code>https://abs.example.com</code>.</p><table tabindex="0"><thead><tr><th>Rule</th><th>Behaviour</th></tr></thead><tbody><tr><td>Unparseable by <code>new URL()</code></td><td>Server exits with an error</td></tr><tr><td>Scheme other than <code>http</code>/<code>https</code></td><td>Server exits with an error</td></tr><tr><td>Contains <code>user:pass@</code></td><td>Server exits with an error</td></tr><tr><td>Trailing slashes</td><td>Stripped</td></tr><tr><td>Plain <code>http</code> to a remote host</td><td>Warning on stderr, server continues</td></tr><tr><td>Plain <code>http</code> to loopback</td><td>No warning</td></tr></tbody></table><p>Loopback means <code>localhost</code>, <code>*.localhost</code>, <code>127.*</code> or <code>::1</code>.</p><h2 id="audiobookshelf-api-key" tabindex="-1"><code>AUDIOBOOKSHELF_API_KEY</code> <a class="header-anchor" href="#audiobookshelf-api-key" aria-label="Permalink to “AUDIOBOOKSHELF_API_KEY”">​</a></h2><p><strong>Required.</strong> Sent as <code>Authorization: Bearer &lt;key&gt;</code>. Created under <strong>Settings → Users → API Keys</strong> (admin only, Audiobookshelf 2.26.0 or newer) and shown once at creation.</p><p>Deleted from <code>process.env</code> after the configuration is read, so it is not visible to child processes or in <code>/proc/&lt;pid&gt;/environ</code>.</p><p>Missing credentials are not fatal: the server starts, completes the handshake and lists all 44 tools, and every call then fails with the setup instructions.</p><h2 id="audiobookshelf-read-only" tabindex="-1"><code>AUDIOBOOKSHELF_READ_ONLY</code> <a class="header-anchor" href="#audiobookshelf-read-only" aria-label="Permalink to “AUDIOBOOKSHELF_READ_ONLY”">​</a></h2><p><strong>Optional</strong>, default <code>false</code>. Exactly the string <code>true</code> enables it — <code>1</code>, <code>yes</code> and <code>TRUE</code> do not, and the difference fails open, with the write tools registered. The server logs the active setting at startup.</p><p>When enabled, the 15 write tools are never registered; <code>tools/list</code> returns 29.</p><h2 id="audiobookshelf-insecure-tls" tabindex="-1"><code>AUDIOBOOKSHELF_INSECURE_TLS</code> <a class="header-anchor" href="#audiobookshelf-insecure-tls" aria-label="Permalink to “AUDIOBOOKSHELF_INSECURE_TLS”">​</a></h2><p><strong>Optional</strong>, default <code>false</code>. Exactly the string <code>true</code> enables it.</p><p>Accepts self-signed and untrusted certificates <strong>for the Audiobookshelf connection only</strong>, via a scoped undici dispatcher. It does not set <code>NODE_TLS_REJECT_UNAUTHORIZED</code> and does not affect any other request the process makes. A warning is printed to stderr while it is active.</p><p>Prefer adding your CA to the system trust store.</p><h2 id="not-configurable" tabindex="-1">Not configurable <a class="header-anchor" href="#not-configurable" aria-label="Permalink to “Not configurable”">​</a></h2><table tabindex="0"><thead><tr><th>Behaviour</th><th>Value</th></tr></thead><tbody><tr><td>Request timeout</td><td>15 s</td></tr><tr><td>HTTP redirects</td><td>never followed</td></tr><tr><td>List cap</td><td>100 entries</td></tr><tr><td>Description cap</td><td>800 characters</td></tr><tr><td>Error body cap</td><td>2000 chars</td></tr><tr><td>Confirm-token TTL</td><td>5 minutes</td></tr><tr><td>Pending tokens</td><td>max 100</td></tr></tbody></table>`,19)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};